'use strict';

// MAIN //

/**
* Creates a self-contained stored-record envelope.
*
* @param {Object} candidate - validated report candidate
* @param {Object} context - harvest context
* @returns {Object} stored record
*/
function createEnvelope( candidate, context ) {
	return {
		'schema': 'stored-record-v1',
		'harvest': {
			'library_id': context.library.id,
			'source_id': context.source.id,
			'source_fingerprint': context.sourceFingerprint,
			'series_schema': candidate.seriesSchema,
			'series_key': candidate.seriesKey,
			'retrieved_at': context.retrievedAt,
			'report_sha256': candidate.reportSha256,
			'origin': Object.assign( {}, structuredClone( context.origin ), {
				'payload': Object.assign( {
					'format': context.payloadFormat
				}, candidate.member ? { 'member': candidate.member } : {} )
			} )
		},
		'report': candidate.report
	};
}


// EXPORTS //

module.exports = createEnvelope;
